const rawInput = $input.all();
const ctx = $('Code - Evaluar Resultados RPC').item.json;
let products = [];

for (const item of rawInput) {
  if (Array.isArray(item.json)) {
    products.push(...item.json);
  } else if (item.json && item.json.id && item.json.name) {
    products.push(item.json);
  }
}
products = products.filter(p => p && p.id && p.name);

const dname = (!ctx.is_generic_name) ? ` *${ctx.client_name}*` : '';
let respText = '';
let foundId = null;
let newStatus = 'pending';
let buttons = [];

if (products.length === 1) {
  const p = products[0];
  foundId = p.id;
  newStatus = 'waiting_product_approval';
  respText = `😔 No encontré coincidencia exacta con *"${ctx.search_term}"*\n\n💡 Pero encontré este producto para ti${dname}:\n\n📦 *${p.name}*\n📝 ${p.description || ''}\n💰 Precio: $${parseFloat(p.price || 0).toFixed(2)}\n📊 Stock: ${p.stock} unidades\n\n¿Deseas agregarlo a tu carrito?`;
  buttons = [
    { id: "si", title: "🛒 Agregar al Carrito" },
    { id: "ver inventario", title: "🔄 Ver Otros" },
    { id: "cancelar", title: "❌ Cancelar" }
  ];
} else if (products.length > 1) {
  const hasKeyword = !!ctx.primary_keyword;
  const header = hasKeyword
    ? `😔 No encontré coincidencia exacta con *"${ctx.search_term}"*\n\n💡 Encontré estas opciones relacionadas. Toca una para ver detalles:`
    : `🛍️ *PRODUCTOS DISPONIBLES*\n\nToca una opción para ver sus detalles:`;

  let listTxt = products.map((p, i) => `${i + 1}️⃣ *${p.name}* — $${parseFloat(p.price || 0).toFixed(2)}`).join('\n');
  respText = `${header}\n\n${listTxt}`;
  buttons = products.slice(0, 3).map(p => ({
    id: p.name,
    title: p.name.slice(0, 20)
  }));
} else {
  respText = `😔 Lo siento${dname}, no encontré productos con *"${ctx.search_term}"* en este momento.\n\n¿Quieres intentar buscando otra cosa?`;
  buttons = [
    { id: "ver inventario", title: "📦 Ver Catálogo" },
    { id: "menu", title: "🏠 Menú Principal" }
  ];
}

return {
  client_id: ctx.client_id,
  client_number: ctx.client_number,
  session_id: ctx.session_id,
  search_term: ctx.search_term,
  found_product_id: foundId,
  response_text: respText,
  buttons: buttons,
  new_status: newStatus
};

const item = $input.item.json;
const dname = (!item.is_generic_name) ? ` *${item.client_name}*,` : '';

const respText = `🛍️ Encontré esto para ti${dname}\n\n📦 *${item.product_name}*\n📝 ${item.product_description || ''}\n💰 Precio: $${item.product_price} COP\n📊 Stock disponible: ${item.product_stock} unidades\n\n¿Cuántas unidades deseas agregar a tu carrito?`;

const buttons = [
  { id: "1", title: "1️⃣ Llevar 1 unidad" },
  { id: "2", title: "2️⃣ Llevar 2 unidades" },
  { id: "3", title: "3️⃣ Llevar 3 unidades" }
];

return {
  client_id: item.client_id,
  client_number: item.client_number,
  session_id: item.session_id,
  search_term: item.search_term,
  found_product_id: item.product_id,
  response_text: respText,
  buttons: buttons,
  new_status: 'waiting_product_approval'
};

const rawInput = $input.all();
const ctx = $('Parsear Respuesta IA').item.json;
let products = [];

for (const item of rawInput) {
  if (Array.isArray(item.json)) {
    products.push(...item.json);
  } else if (item.json && item.json.id && item.json.name) {
    products.push(item.json);
  }
}

// Filtro estricto para eliminar objetos vacíos {} o nulos
products = products.filter(p => p && p.id && p.name);

if (products.length > 0) {
  const p = products[0];
  return {
    has_exact_match: true,
    product_id: p.id,
    product_name: p.name,
    product_description: p.description || '',
    product_price: parseFloat(p.price || 0).toFixed(2),
    product_stock: p.stock || 0,
    search_term: ctx.search_term,
    client_name: ctx.client_name,
    is_generic_name: ctx.is_generic_name,
    client_id: ctx.client_id,
    client_number: ctx.client_number,
    session_id: ctx.session_id
  };
}

// Extraer palabras clave si no hubo coincidencia exacta
const rawSearch = (ctx.search_term || '').toLowerCase();
const stopWords = new Set(['de','la','un','una','el','los','las','para','con','en','del','por','busco','quiero','necesito','me','gustaria']);
const words = rawSearch.split(/\s+/).filter(w => w.length > 2 && !stopWords.has(w));
const primaryKeyword = words[0] || '';

return {
  has_exact_match: false,
  primary_keyword: primaryKeyword,
  all_keywords: words,
  search_term: ctx.search_term,
  client_name: ctx.client_name,
  is_generic_name: ctx.is_generic_name,
  client_id: ctx.client_id,
  client_number: ctx.client_number,
  session_id: ctx.session_id
};

const prodItem = $input.item.json;
const product = Array.isArray(prodItem) ? prodItem[0] : (prodItem || {});
const ctx = $('Parsear Respuesta IA').item.json;

let itemsList = '';
let totalAmount = '0.00';

if (ctx.cart_items && Array.isArray(ctx.cart_items) && ctx.cart_items.length > 0) {
  itemsList = ctx.cart_items.map(item => ` • ${item.quantity || 1}x *${item.name}* ($${parseFloat(item.price || 0).toFixed(2)} c/u) = $${(parseFloat(item.price || 0) * (item.quantity || 1)).toFixed(2)}`).join('\n');
  const sum = ctx.cart_items.reduce((acc, item) => acc + (parseFloat(item.price || 0) * (item.quantity || 1)), 0);
  totalAmount = sum.toFixed(2);
} else {
  const prodName = product.name || 'Producto';
  const prodPrice = product.price ? parseFloat(product.price).toFixed(2) : '0.00';
  itemsList = ` • 1x *${prodName}* — $${prodPrice}`;
  totalAmount = prodPrice;
}

const address = ctx.delivery_address || 'No requerida / no especificada';
const mediaUrl = ctx.media_url || 'No adjunta';

const bizMsg = `📲 *NUEVA EVIDENCIA DE PAGO RECIBIDA*\n\n` +
`👤 *Cliente:* ${ctx.client_name} (${ctx.client_number})\n` +
`📦 *PRODUCTOS COMPRADOS:*\n${itemsList}\n` +
`────────────────────────────\n` +
`💰 *TOTAL A VALIDAR:* $${totalAmount} COP\n` +
`💳 *Método de Pago:* ${ctx.payment_method || 'No especificado'}\n` +
`🏠 *Dirección:* ${address}\n` +
`📸 *Evidencia:* ${mediaUrl}\n\n` +
`🆔 *ID de Sesión:* ```${ctx.session_id}```\n\n` +
`👇 *Toca un botón para autorizar, rechazar o chatear:*`;

const buttons = [
  { id: `aprobar ${ctx.session_id}`, title: "✅ Aprobar Pago" },
  { id: `rechazar ${ctx.session_id}`, title: "❌ Rechazar Pago" },
  { id: `pausar bot ${ctx.client_number}`, title: "💬 Chatear Cliente" }
];

return {
  admin_number: (ctx.tenant ? ctx.tenant.number : (ctx.admin_number || '521234567890')),
  biz_notification: bizMsg,
  buttons: buttons,
  client_number: ctx.client_number,
  client_id: ctx.client_id,
  session_id: ctx.session_id
};

const ctx = $input.item.json;
const requireAddress = (($json.tenant ? $json.tenant.require_delivery_address !== false : true) === 'true');
const nextStatus = requireAddress ? 'waiting_delivery_address' : 'waiting_payment_evidence';
const responseMsg = requireAddress
  ? `💳 Método de pago seleccionado: *${ctx.payment_method}*\n\n📍 Por favor ingresa tu *dirección de entrega completa* (calle, número, colonia, ciudad) para enviar tu pedido.`
  : `💳 Método de pago seleccionado: *${ctx.payment_method}*\n\nAhora envía la *foto o captura* de tu comprobante de pago. 📸`;

return {
  ...ctx,
  next_status: nextStatus,
  response_text: responseMsg
};

const ctx = $input.item.json;
return {
  wa_message:    '¡Excelente! Para procesar y confirmar tu compra, por favor dime tu *nombre completo*. 😊',
  client_number: ctx.client_number,
  client_id:     ctx.client_id,
  session_id:    ctx.session_id
};

const bizCmd = $('Parsear Comando de Negocio').item.json;
const items  = $input.all();
let sessionData = null;

if (items.length > 0 && Array.isArray(items[0].json)) {
  sessionData = items[0].json[0] || null;
} else if (items.length > 0 && items[0].json && items[0].json.id) {
  sessionData = items[0].json;
}

if (!sessionData) {
  return {
    found: false,
    action: bizCmd.action,
    identifier: bizCmd.identifier,
    biz_message: `⚠️ No se encontró ninguna sesión activa pendiente de confirmación con el identificador: "${bizCmd.identifier}".`
  };
}

const clientObj = Array.isArray(sessionData.clients) ? sessionData.clients[0] : (sessionData.clients || {});

return {
  found: true,
  session_id: sessionData.id,
  client_id: sessionData.client_id,
  client_number: clientObj.number || '',
  client_name: clientObj.name || 'Cliente',
  action: bizCmd.action,
  identifier: bizCmd.identifier
};

const input = $input.item.json;
const trigger = $('Manual Trigger - Mensaje WhatsApp').item?.json || {};

let waMessage = input.wa_message;
let buttons = Array.isArray(input.buttons) ? input.buttons : [];

// Si la entrada viene de un nodo Supabase que retornó la fila de BD, rescatar el wa_message del nodo Code emisor
if (!waMessage) {
  try { waMessage = $('Code - Confirmar Nombre Registrado').item.json.wa_message; } catch(e) {}
}
if (!waMessage) {
  try { waMessage = $('Code - Formatear Sugerencias o Catálogo').item.json.response_text; } catch(e) {}
}
if (!waMessage) {
  try { waMessage = $('Code - Respuesta Fallback').item.json.wa_message; } catch(e) {}
}
if (buttons.length === 0) {
  try {
    const b = $('Code - Formatear Sugerencias o Catálogo').item.json.buttons;
    if (Array.isArray(b)) buttons = b;
  } catch(e) {}
}
if (buttons.length === 0) {
  try {
    const b = $('Code - Formatear Producto Encontrado').item.json.buttons;
    if (Array.isArray(b)) buttons = b;
  } catch(e) {}
}

const finalMsg = waMessage || input.response || '¿En qué puedo ayudarte?';
const waNumber  = input.wa_number || input.client_number || trigger.number || '573001234567';
const sessionId = input.session_id || input.id || null;
const clientId  = input.client_id || null;

return { wa_number: waNumber, wa_message: finalMsg, buttons: buttons, session_id: sessionId, client_id: clientId };

const ctx = $input.item.json;
const name = (!ctx.is_generic_name) ? ` *${ctx.client_name}*` : '';
const status = ctx.session_status || 'pending';

let msg = '';
switch(status) {
  case 'pending':
    msg = `¡Hola${name}! 👋 Bienvenido/a a nuestra tienda.\n\nTe puedo ayudar a buscar cualquier producto de nuestro catálogo. Simplemente dime qué estás buscando (ejemplo: *"busco una camisa azul"* o *"tenis negros"*).`;
    break;
  case 'waiting_product_approval':
    msg = `Actualmente tienes un producto mostrado.\n\nResponde *SÍ* para comprarlo, *NO* para buscar otro producto, o dime qué otra cosa estás buscando.`;
    break;
  case 'select_payment':
    msg = `Por favor dinos cuál es tu método de pago preferido (transferencia, efectivo o tarjeta).`;
    break;
  case 'waiting_delivery_address':
    msg = `Por favor ingresa tu dirección de entrega completa para continuar con tu pedido.`;
    break;
  case 'waiting_payment_evidence':
    msg = `Por favor envía la foto o captura de tu comprobante de pago para verificar tu pedido. 📸`;
    break;
  case 'waiting_business_confirmation':
    msg = `Tu comprobante ya está siendo revisado por nuestro equipo. Te notificaremos en breve. ⏳`;
    break;
  default:
    msg = `¡Hola${name}! 👋 ¿En qué te puedo ayudar hoy? Cuéntame qué producto estás buscando.`;
}

return {
  wa_message:    msg,
  client_number: ctx.client_number,
  client_id:     ctx.client_id,
  session_id:    ctx.session_id
};

const ctx = $input.item.json;
const s = ctx.session_status || 'pending';
const msgs = {
  pending:                  '⚠️ Primero necesitas buscar y aprobar un producto.',
  waiting_product_approval: '⚠️ Aún no aprobaste el producto. ¿Deseas comprarlo?',
  select_payment:           '💳 Primero indica tu método de pago antes del comprobante.'
};
return { wa_message: msgs[s] || '⚠️ No esperaba un comprobante en este momento.', client_number: ctx.client_number, client_id: ctx.client_id, session_id: ctx.session_id };

const ctx = $input.item.json;
const s = ctx.session_status || 'pending';
const msgs = {
  pending:                  '🔍 Primero busca y aprueba un producto. ¿Qué estás buscando?',
  waiting_product_approval: '📦 Aún no confirmaste el producto. Responde *SÍ* o *NO*.',
  waiting_payment_evidence: '📸 Ya registramos tu pago. Solo falta el comprobante.',
  waiting_business_confirmation: '⏳ Tu pago ya está en revisión.'
};
return { wa_message: msgs[s] || '⚠️ No es el momento de indicar un método de pago.', client_number: ctx.client_number, client_id: ctx.client_id, session_id: ctx.session_id };

const ctx = $input.item.json;
const s = ctx.session_status || 'pending';
const msgs = {
  pending:                      '🔍 Aún no tenemos un producto para aprobar. ¿Qué estás buscando?',
  select_payment:               '💳 Ya aprobaste el producto. Por favor elige tu método de pago.',
  waiting_payment_evidence:     '📸 Ya elegiste el pago. Envía tu comprobante para continuar.',
  waiting_business_confirmation:'⏳ Tu pago ya está en revisión. Espera la confirmación del negocio.'
};
return { wa_message: msgs[s] || '⚠️ No hay producto pendiente de aprobación. ¿Qué buscas?', client_number: ctx.client_number, client_id: ctx.client_id, session_id: ctx.session_id };

const updClient = $input.item.json;
const ctx       = $('Parsear Respuesta IA').item.json;
const name      = updClient.name || ctx.extracted_name || 'amigo/a';
const status    = ctx.session_status || 'pending';

let msg = '';
let newStatus = status;

if (status === 'waiting_product_approval') {
  // El cliente proporcionó su nombre después de aprobar un producto
  // Avanzamos automáticamente la sesión al estado 'select_payment'
  newStatus = 'select_payment';
  msg = `¡Mucho gusto, *${name}*! 😊 Ya quedó registrado tu nombre.\n\n✅ ¡Producto aprobado!\n\n💳 ¿Cómo deseas pagar?\n\n1️⃣ Transferencia bancaria\n2️⃣ Efectivo\n3️⃣ Tarjeta de crédito/débito\n\nEscribe el nombre o número de tu método de pago.`;
} else if (status === 'select_payment') {
  msg = `¡Mucho gusto, *${name}*! 😊 Por favor dinos cuál es tu método de pago preferido (transferencia, efectivo o tarjeta).`;
} else if (status === 'waiting_delivery_address') {
  msg = `¡Mucho gusto, *${name}*! 😊 Por favor ingresa tu dirección de entrega completa para continuar con tu pedido.`;
} else if (status === 'waiting_payment_evidence') {
  msg = `¡Mucho gusto, *${name}*! 😊 Por favor envía la foto o captura de tu comprobante de pago. 📸`;
} else {
  msg = `¡Mucho gusto, *${name}*! 😊 Ya quedó registrado tu nombre.\n\n¿Qué producto estás buscando hoy?`;
}

return {
  client_id:     ctx.client_id,
  client_number: ctx.client_number,
  session_id:    ctx.session_id,
  wa_message:    msg,
  new_status:    newStatus
};

const ctx = $input.item.json;
return {
  wa_message:    `¡Hola, *${ctx.client_name}*! 👋 Bienvenido/a a nuestra tienda.\n\n¿Qué producto estás buscando hoy?`,
  client_number: ctx.client_number,
  client_id:     ctx.client_id,
  session_id:    ctx.session_id
};

const ctx = $input.item.json;
return {
  wa_message:    '¡Hola! 👋 Bienvenido/a a nuestra tienda.\n\n¿Cuál es tu nombre y qué producto estás buscando hoy?',
  client_number: ctx.client_number,
  client_id:     ctx.client_id,
  session_id:    ctx.session_id
};

const ctx = $('Parsear Respuesta IA').item.json;
return {
  wa_message:    '🔍 Con gusto te ayudo a buscar.\n\n¿Qué producto estás buscando? Puedes describirlo con color, talla, modelo o cualquier detalle.',
  client_number: ctx.client_number,
  client_id:     ctx.client_id,
  session_id:    ctx.session_id
};

const raw = $input.item.json.output || $input.item.json.text || '{}';
const ctx = $('Preparar Contexto para IA').item.json;
let p = {};
try { const m = raw.match(/\{[\s\S]*\}/); if (m) p = JSON.parse(m[0]); }
catch(e) { p = { intent:'OTHER', search_term:'', payment_method:'', extracted_name:'', extracted_address:'', confidence:0 }; }

let intent = (p.intent || 'OTHER').toUpperCase();

// Regla 1: si hay imagen y no es cancelación → siempre EVIDENCE
if (ctx.has_media && intent !== 'CANCEL') intent = 'EVIDENCE';

// Regla 2: si la sesión está en waiting_delivery_address y el mensaje no es CANCEL → interpretar como PROVIDE_ADDRESS
if (ctx.session_status === 'waiting_delivery_address' && intent !== 'CANCEL') {
  intent = 'PROVIDE_ADDRESS';
}

// Regla 3: Detección PRECISA de si el bot realmente PIDIÓ el nombre en el turno anterior
if (!ctx.has_media && intent !== 'PROVIDE_ADDRESS') {
  const last = (ctx.last_bot_message || '').toLowerCase();

  // Solo se considera que el bot pidió el nombre si contiene frases explícitas de PREGUNTA
  const botPedioNombre = (
    last.includes('cuál es tu nombre') ||
    last.includes('cual es tu nombre') ||
    last.includes('dime tu nombre') ||
    last.includes('nombre completo') ||
    last.includes('cómo te llamas') ||
    last.includes('como te llamas') ||
    last.includes('decir tu nombre')
  ) && !last.includes('ya quedó registrado') && !last.includes('ya registré');

  if (botPedioNombre && intent !== 'CANCEL') {
    intent = 'PROVIDE_NAME';
    if (!p.extracted_name || p.extracted_name.trim() === '') {
      p.extracted_name = ctx.user_message;
    }
  }
}

return {
  ...ctx,
  intent,
  final_intent:      intent,
  search_term:       (p.search_term       || '').trim(),
  payment_method:    (p.payment_method    || '').trim(),
  extracted_name:    (p.extracted_name    || ctx.user_message || '').trim(),
  extracted_address: (p.extracted_address || ctx.user_message || '').trim(),
  ai_confidence:     p.confidence || 0
};

const input = $input.item.json;
const clientData = $('Merge - Datos de Cliente').item.json;

const sessionId        = input.session_id        || input.id               || null;
const sessionStatus    = input.session_status    || input.status           || 'pending';
const lastBotMessage   = input.session_response   || input.response         || '';
const foundProduct     = input.found_product_id  || null;
const paymentMethod    = input.payment_method    || '';
const deliveryAddress  = input.delivery_address  || '';

const isGenericName = !clientData.client_name || clientData.client_name.startsWith('Cliente ');

return {
  session_id:       sessionId,
  session_status:   sessionStatus,
  found_product_id: foundProduct,
  payment_method:   paymentMethod,
  delivery_address: deliveryAddress,
  last_bot_message: lastBotMessage,
  client_id:        input.client_id      || clientData.client_id,
  client_number:    clientData.client_number,
  client_name:      clientData.client_name,
  is_generic_name:  isGenericName,
  user_message:     clientData.original_message,
  media_url:        clientData.media_url || '',
  has_media:        !!(clientData.media_url && clientData.media_url.trim() !== '')
};

// Lee el resultado del getAll (puede ser {} vacío si no hay sesión)
const items = $input.all();
const session = (items.length > 0 && items[0].json && items[0].json.id) ? items[0].json : null;
const clientData = $('Merge - Datos de Cliente').item.json;
return {
  has_session:     session !== null,
  session_id:      session?.id     || null,
  session_status:  session?.status || 'pending',
  session_response: session?.response || '',
  found_product_id: session?.found_product_id || null,
  payment_method:  session?.payment_method || '',
  client_id:       clientData.client_id
};

const s = $input.item.json;
return {
  client_id:     s.id || s.client_id,
  client_number: s.number || s.client_number,
  client_name:   s.name   || s.client_name,
  original_message: $('Manual Trigger - Mensaje WhatsApp').item.json.message || '',
  media_url:        $('Manual Trigger - Mensaje WhatsApp').item.json.media_url || ''
};

const items = $input.all();
const d = (items.length > 0 && items[0].json && items[0].json.id) ? items[0].json : null;
const num = $('Manual Trigger - Mensaje WhatsApp').item.json.number;
if (d) return { client_id: d.id, client_number: d.number, client_name: d.name, is_new: false };
return { client_id: null, client_number: num, client_name: 'Cliente ' + num, is_new: true };

const rawMsg = ($input.item.json.message || $input.item.json.button_id || '').trim();
let cleanMsg = rawMsg;
if (cleanMsg.startsWith('aprobar_') || cleanMsg.startsWith('rechazar_') || cleanMsg.startsWith('despachar_') || cleanMsg.startsWith('pausar_bot_') || cleanMsg.startsWith('activar_bot_')) {
  cleanMsg = cleanMsg.replace(/_/g, ' ');
}
const parts = cleanMsg.split(/\s+/);
const firstWord = (parts[0] || '').toLowerCase();
const secondWord = (parts[1] || '').toLowerCase();
let identifier = (parts[1] || '').trim();

let action = 'unknown';
if (firstWord === 'pausar' && secondWord === 'bot') {
  action = 'pause_bot';
  identifier = (parts[2] || '').trim();
} else if (firstWord === 'activar' && secondWord === 'bot') {
  action = 'activate_bot';
  identifier = (parts[2] || '').trim();
} else if (['confirm_payment', 'confirmar', 'aprobar', 'aprobado', 'acepto'].includes(firstWord)) {
  action = 'confirm_payment';
} else if (['reject_payment', 'rechazar', 'rechazado', 'cancelar_pago'].includes(firstWord)) {
  action = 'reject_payment';
} else if (['despachos', 'entregas', 'pedidos', 'envios'].includes(firstWord)) {
  action = 'view_dispatches';
} else if (['despachar', 'enviar', 'entregar'].includes(firstWord)) {
  action = 'dispatch_order';
}

const isPhoneNumber = /^\d{8,15}$/.test(identifier);

return {
  raw_message: rawMsg,
  action: action,
  identifier: identifier,
  is_phone_number: isPhoneNumber,
  business_number: $input.item.json.number || ''
};

const item = .item.json;
const tenant = item.tenant || {};
const sender = item.sender || {};
const msg = item.message || {};

const senderType = sender.type || item.sender_type || (sender.number === tenant.number ? business : client);
